<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { clearAdminSession, deleteNews, deletePerson, getAllNews, getPeople, getSettings, hasAdminSession, hasContentRole, isSupabaseConfigured, saveNews, savePerson, saveSettings, signIn } from '../services/contentService.js'

const router = useRouter()
const configured = isSupabaseConfigured()
const authenticated = ref(hasAdminSession() && hasContentRole())
const email = ref(''); const password = ref(''); const error = ref(''); const busy = ref(false)
const tab = ref('news'); const news = ref([]); const people = ref([]); const settings = reactive({}); const editorOpen = ref(false); const editing = ref(null)
const blankNews = () => ({ id: null, slug: '', status: 'draft', publishedAt: new Date().toISOString(), category: 'school', cover: { type: 'pattern', theme: 'school' }, translations: { uz: { categoryLabel: 'Maktab hayoti', title: '', excerpt: '', body: [''] }, ru: { categoryLabel: 'Жизнь школы', title: '', excerpt: '', body: [''] } } })
const toDateInput = value => { const date = new Date(value); return new Date(date.getTime() - date.getTimezoneOffset() * 60000).toISOString().slice(0, 16) }
const blankPerson = () => ({ id: null, role: 'teacher', photo_url: '', sort_order: 0, translations: { uz: { name: '', title: '', quote: '' }, ru: { name: '', title: '', quote: '' } } })
const personDraft = ref(blankPerson())
const personRows = computed(() => people.value)
const message = ref('')
async function refresh() { error.value = ''; try { const [nextNews, nextPeople, nextSettings] = await Promise.all([getAllNews(), getPeople(), getSettings()]); news.value = nextNews; people.value = nextPeople; Object.assign(settings, nextSettings) } catch (e) { error.value = e.message } }
async function login() { busy.value = true; error.value = ''; try { await signIn(email.value, password.value); if (!hasContentRole()) { clearAdminSession(); throw new Error('У этой учётной записи нет прав администратора.') } authenticated.value = true; await refresh() } catch (e) { error.value = e.message } finally { busy.value = false } }
function edit(item) { editing.value = JSON.parse(JSON.stringify(item)); editing.value.publishedAt = toDateInput(item.publishedAt); for (const lang of ['uz', 'ru']) editing.value.translations[lang].body = [editing.value.translations[lang].body.join('\n\n')]; editorOpen.value = true }
function createNews() { editing.value = blankNews(); editing.value.publishedAt = toDateInput(editing.value.publishedAt); editorOpen.value = true }
function addParagraph(lang) { editing.value.translations[lang].body.push('') }
async function submitNews() { busy.value = true; error.value = ''; try { const draft = JSON.parse(JSON.stringify(editing.value)); for (const lang of ['uz', 'ru']) draft.translations[lang].body = draft.translations[lang].body[0].split(/\n\s*\n/).map(text => text.trim()).filter(Boolean); draft.slug ||= draft.translations.uz.title.toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') || crypto.randomUUID(); draft.publishedAt = new Date(draft.publishedAt).toISOString(); await saveNews(draft); editorOpen.value = false; await refresh(); message.value = 'Новость сохранена' } catch (e) { error.value = e.message } finally { busy.value = false } }
async function removeNews(item) { if (!confirm(`Удалить новость «${item.translations?.ru?.title || item.slug}»?`)) return; try { await deleteNews(item.id); await refresh() } catch (e) { error.value = e.message } }
function editPerson(person) { personDraft.value = JSON.parse(JSON.stringify(person)); editing.value = person; }
function createPerson() { personDraft.value = blankPerson(); editing.value = { type: 'person-new' } }
async function submitPerson() { busy.value = true; error.value = ''; try { await savePerson(personDraft.value); editing.value = null; await refresh() } catch (e) { error.value = e.message } finally { busy.value = false } }
async function removePerson(person) { if (!confirm('Удалить эту запись?')) return; try { await deletePerson(person.id); await refresh() } catch (e) { error.value = e.message } }
async function submitSettings() { busy.value = true; error.value = ''; try { await saveSettings({ ...settings }); message.value = 'Информация о школе сохранена' } catch (e) { error.value = e.message } finally { busy.value = false } }
function logout() { clearAdminSession(); authenticated.value = false; router.replace('/') }
onMounted(() => { if (authenticated.value) refresh() })
</script>

<template>
  <main class="admin-page">
    <section v-if="!authenticated" class="admin-login"><a class="admin-back" href="#/">← На сайт</a><div class="admin-login-card"><span class="admin-mark">13</span><p class="eyebrow">13-MAKTAB · CMS</p><h1>Вход в панель</h1><p class="admin-muted">Войдите с учётной записью администратора Supabase.</p><form @submit.prevent="login"><label>Email<input v-model="email" type="email" autocomplete="username" required></label><label>Пароль<input v-model="password" type="password" autocomplete="current-password" required></label><p v-if="!configured" class="admin-hint">Подключите Supabase в <code>.env.local</code>. Пока можно открыть панель в демо-режиме: <a href="#/admin?demo=1" @click.prevent="authenticated = true; refresh()">Продолжить локально</a>.</p><button class="admin-primary" :disabled="busy || !configured">{{ busy ? 'Входим…' : 'Войти' }}</button><p v-if="error" class="admin-error">{{ error }}</p></form></div></section>
    <section v-else class="admin-layout"><aside class="admin-sidebar"><a class="admin-brand" href="#/"><span class="admin-mark">13</span><span>13-MAKTAB<small>ADMIN PANEL</small></span></a><p class="admin-nav-label">УПРАВЛЕНИЕ</p><button v-for="item in [{id:'news',label:'Новости',icon:'✳'},{id:'people',label:'Команда',icon:'♙'},{id:'school',label:'О школе',icon:'⌂'}]" :key="item.id" :class="{active:tab===item.id}" @click="tab=item.id">{{ item.icon }} <span>{{ item.label }}</span><b v-if="item.id==='news'">{{ news.length }}</b></button><div class="admin-sidebar-bottom"><a href="#/">↗ Посмотреть сайт</a><button @click="logout">Выйти</button></div></aside>
      <div class="admin-main"><header class="admin-topbar"><div><span>13-MAKTAB / ADMIN</span><h1>{{ tab==='news'?'Новости':tab==='people'?'Команда':'Информация о школе' }}</h1></div><div class="admin-status"><i :class="configured?'is-connected':''"></i>{{ configured?'Supabase':'Локальный режим' }}</div></header><div v-if="!configured" class="admin-banner">Демо-режим: изменения сохраняются в этом браузере. Задайте ключи Supabase, чтобы включить общую базу.</div><p v-if="error" class="admin-error admin-alert">{{ error }}</p><p v-if="message" class="admin-success">{{ message }}</p>
        <section v-if="tab==='news'" class="admin-content"><div class="admin-section-head"><div><h2>Все публикации</h2><p>Создавайте новости на узбекском и русском языках.</p></div><button class="admin-primary" @click="createNews">＋ Новая новость</button></div><div v-if="editorOpen" class="admin-panel editor-panel"><div class="admin-section-head"><h2>{{ editing.id?'Редактировать новость':'Новая новость' }}</h2><button class="admin-quiet" @click="editorOpen=false">Закрыть ×</button></div><div class="admin-form-grid"><label>Статус<select v-model="editing.status"><option value="draft">Черновик</option><option value="published">Опубликована</option></select></label><label>Категория<select v-model="editing.category"><option value="school">Maktab hayoti / Жизнь школы</option><option value="students">O'quvchilar / Ученики</option><option value="events">Tadbirlar / События</option></select></label><label>Дата публикации<input v-model="editing.publishedAt" type="datetime-local" @change="editing.publishedAt=new Date(editing.publishedAt).toISOString()"></label><label>Ссылка (slug)<input v-model="editing.slug" placeholder="создаётся из заголовка"></label></div><div class="admin-lang-grid"><fieldset v-for="lang in ['uz','ru']" :key="lang"><legend>{{ lang==='uz'?'O‘zbekcha':'Русский' }}</legend><label>Заголовок<input v-model="editing.translations[lang].title" required></label><label>Название категории<input v-model="editing.translations[lang].categoryLabel"></label><label>Краткое описание<textarea v-model="editing.translations[lang].excerpt" rows="2"></textarea></label><label>Текст новости<textarea v-model="editing.translations[lang].body[0]" rows="5" placeholder="Абзацы разделяйте пустой строкой"></textarea></label></fieldset></div><button class="admin-primary" :disabled="busy" @click="submitNews">Сохранить новость</button></div><div class="admin-panel admin-table"><article v-for="item in news" :key="item.id" class="admin-row"><div class="admin-row-icon">{{ item.category==='events'?'✦':item.category==='students'?'♙':'✺' }}</div><div class="admin-row-copy"><span :class="['admin-badge',item.status]">{{ item.status==='published'?'Опубликована':'Черновик' }}</span><h3>{{ item.translations?.ru?.title || item.translations?.uz?.title || item.slug }}</h3><p>{{ item.slug }} · {{ item.category }}</p></div><div class="admin-row-actions"><button @click="edit(item)">Редактировать</button><button class="danger" @click="removeNews(item)">Удалить</button></div></article><p v-if="!news.length" class="admin-empty">Новостей пока нет. Добавьте первую публикацию.</p></div></section>
        <section v-if="tab==='people'" class="admin-content"><div class="admin-section-head"><div><h2>Учителя и ученики</h2><p>Записи появятся в секции команды на сайте.</p></div><button class="admin-primary" @click="createPerson">＋ Добавить человека</button></div><div v-if="editing && (editing.type==='person-new' || editing.role)" class="admin-panel editor-panel"><div class="admin-section-head"><h2>Карточка команды</h2><button class="admin-quiet" @click="editing=null">Закрыть ×</button></div><div class="admin-form-grid"><label>Тип<select v-model="personDraft.role"><option value="teacher">Учитель</option><option value="student">Ученик</option></select></label><label>Фото (URL)<input v-model="personDraft.photo_url" placeholder="https://…"></label><label>Порядок<input v-model.number="personDraft.sort_order" type="number"></label></div><div class="admin-lang-grid"><fieldset v-for="lang in ['uz','ru']" :key="lang"><legend>{{ lang==='uz'?'O‘zbekcha':'Русский' }}</legend><label>Имя / заголовок<input v-model="personDraft.translations[lang].name"></label><label>Роль или достижение<input v-model="personDraft.translations[lang].title"></label><label>Цитата<textarea v-model="personDraft.translations[lang].quote" rows="3"></textarea></label></fieldset></div><button class="admin-primary" :disabled="busy" @click="submitPerson">Сохранить</button></div><div class="admin-panel admin-table"><article v-for="person in personRows" :key="person.id" class="admin-row"><div class="admin-row-icon">{{ person.role==='student'?'♙':'✳' }}</div><div class="admin-row-copy"><span class="admin-badge published">{{ person.role==='student'?'Ученик':'Учитель' }}</span><h3>{{ person.translations?.ru?.name || person.translations?.uz?.name }}</h3><p>{{ person.translations?.ru?.title || person.translations?.uz?.title }}</p></div><div class="admin-row-actions"><button @click="editPerson(person)">Редактировать</button><button class="danger" @click="removePerson(person)">Удалить</button></div></article><p v-if="!people.length" class="admin-empty">Пока сайт показывает две демонстрационные карточки. Добавленные записи из базы будут отображаться здесь и на сайте.</p></div></section>
        <section v-if="tab==='school'" class="admin-content"><div class="admin-section-head"><div><h2>О школе</h2><p>Этот текст виден в основном блоке сайта на двух языках.</p></div></div><div class="admin-panel school-editor"><fieldset><legend>O‘zbekcha</legend><label>Заголовок<input v-model="settings.about_title_uz"></label><label>Текст<textarea v-model="settings.about_text_uz" rows="5"></textarea></label><label>Подпись статистики 1<input v-model="settings.stat_label_1_uz"></label><label>Подпись статистики 2<input v-model="settings.stat_label_2_uz"></label><label>Подпись статистики 3<input v-model="settings.stat_label_3_uz"></label></fieldset><fieldset><legend>Русский</legend><label>Заголовок<input v-model="settings.about_title_ru"></label><label>Текст<textarea v-model="settings.about_text_ru" rows="5"></textarea></label><label>Подпись статистики 1<input v-model="settings.stat_label_1_ru"></label><label>Подпись статистики 2<input v-model="settings.stat_label_2_ru"></label><label>Подпись статистики 3<input v-model="settings.stat_label_3_ru"></label></fieldset><button class="admin-primary" :disabled="busy" @click="submitSettings">Сохранить информацию</button></div></section>
      </div>
    </section>
  </main>
</template>
